int allocate_pool_memory(const char* init_data, size_t data_len, char* pool_buffer, size_t pool_size)
{
    /* Step 1: Validate pool_buffer is not NULL */
    if (pool_buffer == NULL) {
        return -1;
    }

    /* Step 2: Validate pool_size can hold the header (used length field) */
    size_t header_size = sizeof(size_t);
    if (pool_size < header_size) {
        return -1;
    }

    /* Step 3: Read current used length from the start of the pool */
    size_t used;
    memcpy(&used, pool_buffer, sizeof(size_t));

    /* Step 4: Calculate available space in allocatable region */
    size_t allocatable_region_size = pool_size - header_size;

    /* Step 5: Handle init_data == NULL case */
    if (init_data == NULL) {
        if (data_len != 0) {
            /* Invalid parameter: NULL data but non-zero length */
            return -1;
        }
        /* data_len == 0, nothing to allocate, success */
        return 0;
    }

    /* Step 6: init_data != NULL, need to allocate data_len bytes */

    /* Validate that current used value is within bounds (sanity check) */
    if (used > allocatable_region_size) {
        return -1;
    }

    /* 
     * Check if there's enough space for the new allocation
     * Using subtraction to avoid potential overflow: 
     * instead of checking (used + data_len <= allocatable_region_size)
     * we check (data_len <= allocatable_region_size - used)
     */
    if (data_len > allocatable_region_size - used) {
        return -1;
    }

    /* Calculate destination address within the pool */
    size_t offset = header_size + used;

    /* Copy init_data to the allocated region in the pool */
    memcpy(pool_buffer + offset, init_data, data_len);

    /* Update the used length and write it back to the pool header */
    size_t new_used = used + data_len;
    memcpy(pool_buffer, &new_used, sizeof(size_t));

    return 0;
}
